@dataclass
class QualityResult:
    record_id: str
    indicator: str
    agency: str
    release_date: str
    reference_period: str
    point_in_time_safe: bool
    quality_issues: str
    historical_consensus_available: bool

def make_record_id(row):
    key = "|".join([
        str(row.get("indicator", "")), str(row.get("agency", "")),
        str(row.get("release_date", "")), str(row.get("release_time", "")),
        str(row.get("reference_period", "")), str(row.get("source_url", "")),
    ])
    return sha256(key.encode("utf-8")).hexdigest()[:16]

def validate(row):
    issues = []
    release_date = pd.to_datetime(row.get("release_date"), errors="coerce")
    vintage_date = pd.to_datetime(row.get("vintage_date"), errors="coerce")
    if pd.isna(release_date): issues.append("invalid_release_date")
    if pd.isna(vintage_date): issues.append("invalid_vintage_date")
    if pd.isna(row.get("actual")): issues.append("missing_actual")
    if not str(row.get("source_url", "")).startswith("http"): issues.append("invalid_source_url")
    pit_safe = not pd.isna(release_date) and not pd.isna(vintage_date) and vintage_date <= release_date
    if not pit_safe: issues.append("point_in_time_violation")
    consensus_available = pd.notna(row.get("consensus")) and str(row.get("consensus_source", "")).strip() not in ("", "nan", "None")
    return QualityResult(
        record_id=make_record_id(row),
        indicator=str(row.get("indicator", "")),
        agency=str(row.get("agency", "")),
        release_date=str(row.get("release_date", "")),
        reference_period=str(row.get("reference_period", "")),
        point_in_time_safe=bool(pit_safe),
        quality_issues=";".join(issues),
        historical_consensus_available=bool(consensus_available),
    )

def main():
    df = pd.DataFrame(RECORDS)
    required = [
        "indicator","agency","release_date","release_time","reference_period",
        "actual","previous","revision","consensus","consensus_source",
        "vintage_date","source","source_url"
    ]
    missing = [c for c in required if c not in df.columns]
    if missing: raise RuntimeError(f"Missing required columns: {missing}")
    df["release_date"] = pd.to_datetime(df["release_date"]).dt.strftime("%Y-%m-%d")
    df["vintage_date"] = pd.to_datetime(df["vintage_date"]).dt.strftime("%Y-%m-%d")
    df = df.drop_duplicates(subset=["indicator","agency","release_date","release_time","reference_period","source_url"]).reset_index(drop=True)
    quality = pd.DataFrame([asdict(validate(row)) for _, row in df.iterrows()])
    if quality["record_id"].duplicated().any(): raise RuntimeError("Duplicate record IDs detected.")
    if not quality["point_in_time_safe"].all(): raise RuntimeError("PIT validation failed.")
    if quality["historical_consensus_available"].any(): raise RuntimeError("Historical consensus detected.")
    if not RESEARCH_ONLY: raise RuntimeError("Research-only gate failed.")
    if DECISION_ENGINE_READY: raise RuntimeError("Decision Engine must remain disabled.")
    df = df.sort_values(["release_date","release_time","indicator"]).reset_index(drop=True)
    quality = quality.sort_values(["release_date","indicator"]).reset_index(drop=True)
    df.to_csv(OUTPUT_EVENTS, index=False)
    quality.to_csv(OUTPUT_QUALITY, index=False)
    print("=" * 60)
    print("ECONOMIC HISTORICAL COLLECTOR v1.8")
    print("=" * 60)
    print("Records:", len(df))
    print("PIT safe:", int(quality["point_in_time_safe"].sum()), "/", len(quality))
    print("Historical consensus:", int(quality["historical_consensus_available"].sum()))
    print("Indicators:", df["indicator"].nunique())
    print("Date range:", df["release_date"].min(), "->", df["release_date"].max())
    print("")
    print(df["indicator"].value_counts().to_string())
    print("")
    print("PIT QUALITY GATE: PASS")
    print("RESEARCH-ONLY GATE: PASS")
    print("DECISION ENGINE DISABLED: PASS")

if __name__ == "__main__":
    main()
